/**
 * Context Window Manager — Sliding Window + Running Summary
 *
 * The biggest cost saver: don't send full conversation history every turn.
 *
 * Strategy:
 *   - Keep last 10-15 exchanges verbatim (hot context)
 *   - Older turns get summarized into a running summary
 *   - Summary generated by GPT-4o-mini (~$0.15/1M tokens) instead of
 *     sending 100+ turns to GPT-4o ($2.50/1M tokens)
 *
 * Expected savings: 50-70% on LLM costs for long sessions.
 *
 * This module enhances the existing context-manager.js without replacing it.
 * It adds a summarize-and-compress capability that the DM service calls
 * periodically.
 */

'use strict';

const crypto = require('crypto');

// Configurable thresholds
const TURNS_BEFORE_SUMMARY = parseInt(process.env.SUMMARY_AFTER_TURNS) || 15;
const MAX_SUMMARY_CHARS = parseInt(process.env.MAX_SUMMARY_CHARS) || 1500;
const SUMMARY_MODEL = 'gpt-4o-mini'; // Always use mini for summaries (cheap)

/**
 * Create a context compressor for a session.
 *
 * @param {object} opts
 * @param {function} opts.llmProvider - LLM provider function for generating summaries
 * @returns {object} Compressor with compress() and getSummary() methods
 */
function createContextCompressor(opts = {}) {
  const state = {
    runningSummary: '',
    summarizedTurns: 0,
    totalTurnsProcessed: 0,
    lastSummaryAt: 0,
    summaryHistory: [],  // Previous summaries for reference
  };

  // Dedicated mini-provider for summaries (always mini, always cheap)
  let summaryProvider = opts.llmProvider || null;

  return {
    get runningSummary() { return state.runningSummary; },
    get summarizedTurns() { return state.summarizedTurns; },
    get totalTurnsProcessed() { return state.totalTurnsProcessed; },

    /**
     * Set the LLM provider to use for summary generation.
     */
    setProvider(provider) {
      summaryProvider = provider;
    },

    /**
     * Check if the context should be compressed.
     * @param {Array} hotTurns - Current hot context turns
     * @returns {boolean}
     */
    shouldCompress(hotTurns) {
      return hotTurns.length >= TURNS_BEFORE_SUMMARY;
    },

    /**
     * Compress old turns into the running summary.
     * Removes the oldest turns from hot context and generates a summary.
     *
     * @param {Array} turnsToCompress - The old turns to summarize
     * @param {object} adventureContext - Adventure info for better summaries
     * @returns {Promise<string>} The updated running summary
     */
    async compress(turnsToCompress, adventureContext = {}) {
      if (!turnsToCompress || turnsToCompress.length === 0) {
        return state.runningSummary;
      }

      // Build a transcript of the turns to summarize
      const transcript = turnsToCompress
        .map(t => `[${t.role}]: ${t.content}`)
        .join('\n');

      // Build the summary prompt
      const summaryPrompt = buildSummaryPrompt(
        transcript,
        state.runningSummary,
        adventureContext
      );

      let newSummary;
      if (summaryProvider) {
        try {
          newSummary = await summaryProvider([
            { role: 'system', content: SUMMARY_SYSTEM_PROMPT },
            { role: 'user', content: summaryPrompt },
          ]);
        } catch (err) {
          console.warn('[ContextCompressor] Summary generation failed:', err.message);
          // Fallback: simple concatenation
          newSummary = buildFallbackSummary(turnsToCompress, state.runningSummary);
        }
      } else {
        // No provider — use heuristic summary
        newSummary = buildFallbackSummary(turnsToCompress, state.runningSummary);
      }

      // Enforce max length
      if (newSummary.length > MAX_SUMMARY_CHARS) {
        newSummary = newSummary.substring(0, MAX_SUMMARY_CHARS) + '...';
      }

      // Update state
      state.summaryHistory.push(state.runningSummary);
      if (state.summaryHistory.length > 5) state.summaryHistory.shift();
      state.runningSummary = newSummary;
      state.summarizedTurns += turnsToCompress.length;
      state.totalTurnsProcessed += turnsToCompress.length;
      state.lastSummaryAt = Date.now();

      console.log(
        `[ContextCompressor] Compressed ${turnsToCompress.length} turns. ` +
        `Summary: ${newSummary.length} chars. Total summarized: ${state.summarizedTurns}`
      );

      return newSummary;
    },

    /**
     * Get the current running summary.
     */
    getSummary() {
      return state.runningSummary;
    },

    /**
     * Get compression stats.
     */
    getStats() {
      return {
        summaryLength: state.runningSummary.length,
        summarizedTurns: state.summarizedTurns,
        totalTurnsProcessed: state.totalTurnsProcessed,
        lastSummaryAt: state.lastSummaryAt,
        previousSummaries: state.summaryHistory.length,
      };
    },

    /**
     * Serialize state for persistence.
     */
    serialize() {
      return { ...state };
    },

    /**
     * Restore state from serialized data.
     */
    deserialize(data) {
      if (data) {
        Object.assign(state, data);
      }
    },
  };
}

/**
 * System prompt for the summary generator.
 */
const SUMMARY_SYSTEM_PROMPT = `You are a story summarizer for a D&D-style text adventure game.

Your job: condense a sequence of game turns into a concise, information-dense summary.

RULES:
- Preserve ALL key events, NPC interactions, items found, decisions made
- Preserve the emotional tone and atmosphere
- Preserve location changes and scene transitions
- Preserve any rules calls (dice rolls, combat, skill checks)
- Preserve character HP changes, coin rewards, inventory changes
- Omit flowery narration — keep only plot-relevant details
- Use present tense, bullet-like prose
- Maximum 300 words

FORMAT:
Write the summary as a flowing narrative paragraph, not bullet points.
Focus on: WHERE the player is, WHAT just happened, WHAT items/info they have, WHAT the immediate situation is.`;

/**
 * Build a prompt for the summary generator.
 */
function buildSummaryPrompt(transcript, existingSummary, adventureContext) {
  let prompt = '';

  if (existingSummary) {
    prompt += `EXISTING SUMMARY (update this with the new events below):\n${existingSummary}\n\n`;
  }

  prompt += `NEW TURNS TO SUMMARIZE:\n${transcript}\n\n`;

  if (adventureContext.adventureName) {
    prompt += `ADVENTURE: ${adventureContext.adventureName}\n`;
  }
  if (adventureContext.currentScene) {
    prompt += `CURRENT SCENE: ${adventureContext.currentScene}\n`;
  }

  prompt += '\nGenerate an updated summary that merges the existing summary with the new events.';

  return prompt;
}

/**
 * Fallback summary when no LLM is available.
 * Simple extraction of key information.
 */
function buildFallbackSummary(turns, existingSummary) {
  const parts = [];

  if (existingSummary) {
    parts.push(existingSummary);
  }

  for (const turn of turns) {
    const content = turn.content || '';
    // Extract key sentences (first sentence of each turn)
    const sentences = content.split(/[.!?]+/).filter(s => s.trim().length > 10);
    if (sentences.length > 0) {
      parts.push(sentences[0].trim());
    }
  }

  let summary = parts.join('. ');
  if (summary.length > MAX_SUMMARY_CHARS) {
    summary = summary.substring(0, MAX_SUMMARY_CHARS) + '...';
  }
  return summary;
}

module.exports = {
  createContextCompressor,
  TURNS_BEFORE_SUMMARY,
  MAX_SUMMARY_CHARS,
  SUMMARY_MODEL,
};
